package org.springframework.amqp.core; import java.util.*; public class MessageProperties { private String id,ct; private final Map<String,Object> h=new LinkedHashMap<>(); public void setMessageId(String v){id=v;} public void setContentType(String v){ct=v;} public void setHeader(String n,Object v){h.put(n,v);} public Map<String,Object> getHeaders(){return h;} public String getContentType(){return ct;} }
